            trancheId,
            _currency
        );
        require(
            liquidityPool != address(0),
            "InvestmentManager/tranche-does-not-exist"
        );
        require(
            _currency == LiquidityPoolLike(liquidityPool).asset(),
            "InvestmentManager/not-tranche-currency"
        );

        SafeTransferLib.safeTransferFrom(
            _currency,
            address(escrow),
            user,
            currencyPayout
        );
    }
```

